package com.hbm.satellite.control;
import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Exact source3machine+36player slots, including original unusual slot0-only quick extraction boundary. */
public final class SatelliteLinkerMenu extends AbstractContainerMenu {
 public final SatelliteLinkerBlockEntity machine;public SatelliteLinkerMenu(int id,Inventory player,RegistryFriendlyByteBuf buffer){this(id,player,(SatelliteLinkerBlockEntity)player.player.level().getBlockEntity(buffer.readBlockPos()));}public SatelliteLinkerMenu(int id,Inventory player,SatelliteLinkerBlockEntity machine){super(SatelliteControlContent.MENU.get(),id);this.machine=machine;addSlot(new Slot(machine,0,44,36));addSlot(new Slot(machine,1,80,36));addSlot(new Slot(machine,2,116,36));for(int i=0;i<27;i++)addSlot(new Slot(player,9+i,8+i%9*18,104+i/9*18));for(int i=0;i<9;i++)addSlot(new Slot(player,i,8+i*18,162));}
 @Override public boolean stillValid(Player player){return machine.stillValid(player);}@Override public ItemStack quickMoveStack(Player player,int index){if(index<0||index>=slots.size())return ItemStack.EMPTY;var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var stack=slot.getItem();var original=stack.copy();if(index<=0){if(!moveItemStackTo(stack,1,slots.size(),true))return ItemStack.EMPTY;}else if(!moveItemStackTo(stack,0,1,false))return ItemStack.EMPTY;if(stack.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return original;}
}
